TABLE IF EXISTS `admin_notification`;CREATE TABLE `admin_notification`  (                                       `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',                                       `admin_id` bigint UNSIGNED NOT NULL COMMENT '接收人管理员 id',                                       `category` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '{system:系统,friend:好友}',                                       `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',                                       `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '正文',                                       `read_at` datetime NULL DEFAULT NULL COMMENT '已读时间，空为未读',                                       `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',                                       PRIMARY KEY (`id`) USING BTREE,                                       INDEX `idx_admin_read_time`(`admin_id` ASC, `read_at` ASC, `create_time` ASC) USING BTREE) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管理员站内通知' ROW_FORMAT = Dynamic;-- ------------------------------ Records of admin_notification-- ------------------------------ ------------------------------ Table structure for admin_operation_log-- ----------------------------DROP TABLE IF EXISTS `admin_operation_log`;CREATE TABLE `admin_operation_log`  (                                        `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',                                        `admin_id` bigint UNSIGNED NOT NULL COMMENT '管理员 id',                                        `action` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作标识，如 profile.update',                                        `summary` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '简述',                                        `ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '客户端 IP',                                        `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',                                        PRIMARY KEY (`id`) USING BTREE,                                        INDEX `idx_admin_time`(`admin_id` ASC, `create_time` ASC) USING BTREE) ENGINE = InnoDB AUTO_INCREMENT = 341 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管理员操作日志' ROW_FORMAT = Dynamic;-- ------------------------------ Records of admin_operation_log-- ------------------------------ ------------------------------ Table structure for admin_role-- ----------------------------DROP TABLE IF EXISTS `admin_role`;CREATE TABLE `admin_role`  (                               `admin_id` bigint UNSIGNED NOT NULL,                               `role_id` bigint UNSIGNED NOT NULL,                               `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '{1:启用,0:停用}',                               PRIMARY KEY (`admin_id`, `role_id`) USING BTREE,                               INDEX `idx_role`(`role_id` ASC) USING BTREE) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;-- ------------------------------ Records of admin_role-- ------------------------------ ------------------------------ Table structure for auth_role-- ----------------------------DROP TABLE IF EXISTS `auth_role`;CREATE TABLE `auth_role`  (                              `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',                              `pid` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '父级 id，0 为根（仅展示，无权限继承）',                              `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色名',                              `desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',                              `sort` int NOT NULL DEFAULT 0 COMMENT '排序',                              `status` tinyint NOT NULL DEFAULT 1 COMMENT '{1:启用,0:禁用}',                              `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',                              `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',                              PRIMARY KEY (`id`) USING BTREE,                              INDEX `idx_pid`(`pid` ASC) USING BTREE) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '权限角色' ROW_FORMAT = Dynamic;-- ------------------------------ Records of auth_role-- ------------------------------ ------------------------------ Table structure for auth_role_rule-- ----------------------------DROP TABLE IF EXISTS `auth_role_rule`;CREATE TABLE `auth_role_rule`  (                                   `role_id` bigint UNSIGNED NOT NULL COMMENT '角色 id',                                   `rule_id` bigint UNSIGNED NOT NULL COMMENT 'auth_rule.id，且 scope=frontend',                                   PRIMARY KEY (`role_id`, `rule_id`) USING BTREE,                                   INDEX `idx_rule`(`rule_id` ASC) USING BTREE) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '角色-前端规则' ROW_FORMAT = Dynamic;-- ------------------------------ Records of auth_role_rule-- ------------------------------ ------------------------------ Table structure for auth_rule-- ----------------------------DROP TABLE IF EXISTS `auth_rule`;CREATE TABLE `auth_rule`  (                              `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',                              `scope` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '{backend:后端,frontend:前端}',                              `type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'backend:{menu,api} frontend:{menu,view,btn}',                              `pid` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '父级 id，0 为根',                              `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',                              `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '后端 api 路径或前端 path 片段',                              `method` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'HTTP 方法，api 用，如 GET POST *',                              `component` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '前端组件路径，view 用',                              `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '图标：{ep:ElementPlus图标组件名,url:图片绝对或相对地址}',                              `sort` int NOT NULL DEFAULT 0 COMMENT '排序',                              `status` tinyint NOT NULL DEFAULT 1 COMMENT '{1:启用,0:禁用}',                              `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',                              `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',                              PRIMARY KEY (`id`) USING BTREE,                              INDEX `idx_scope_pid`(`scope` ASC, `pid` ASC) USING BTREE,                              INDEX `idx_scope_status`(`scope` ASC, `status` ASC) USING BTREE) ENGINE = InnoDB AUTO_INCREMENT = 683 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '权限规则（后端/前端双域树）' ROW_FORMAT = Dynamic;-- ------------------------------ Records of auth_rule-- ------------------------------ ------------------------------ Table structure for auth_rule_frontend_api-- ----------------------------DROP TABLE IF EXISTS `auth_rule_frontend_api`;CREATE TABLE `auth_rule_frontend_api`  (                                           `frontend_rule_id` bigint UNSIGNED NOT NULL COMMENT 'auth_rule id，scope=frontend 且 type 为 view 或 btn',                                           `backend_rule_id` bigint UNSIGNED NOT NULL COMMENT 'auth_rule id，scope=backend 且 type=api',                                           PRIMARY KEY (`frontend_rule_id`, `backend_rule_id`) USING BTREE,                                           INDEX `idx_backend`(`backend_rule_id` ASC) USING BTREE) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '前端规则-后端接口' ROW_FORMAT = Dynamic;-- ------------------------------ Records of auth_rule_frontend_api-- ------------------------------ ------------------------------ Table structure for demo_all_type_tag-- ----------------------------DROP TABLE IF EXISTS `demo_all_type_tag`;CREATE TABLE `demo_all_type_tag`  (                                      `all_type_id` bigint UNSIGNED NOT NULL COMMENT 'demo_all_type.id',                                      `tag_id` bigint UNSIGNED NOT NULL COMMENT '关联 id',                                      PRIMARY KEY (`all_type_id`, `tag_id`) USING BTREE,                                      INDEX `idx_tag_id`(`tag_id` ASC) USING BTREE) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '全字段类型-标签' ROW_FORMAT = DYNAMIC;-- ------------------------------ Records of demo_all_type_tag-- ------------------------------ ------------------------------ Table structure for dev_crud_history-- ----------------------------DROP TABLE IF EXISTS `dev_crud_history`;CREATE TABLE `dev_crud_history`  (                                     `id` int UNSIGNED NOT NULL AUTO_INCREMENT,                                     `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '方案名',                                     `config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '方案配置',                                     `fields` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '字段配置',                                     `create_time` datetime NOT NULL COM